    expect(getCachedProbe("p2", "k")).toBeNull();
    expect(getCachedProbe("p1", "k2")).toBeNull();
  });

  it("expires connected entries after 60s", () => {
    vi.useFakeTimers();
    vi.setSystemTime(0);
    setCachedProbe("p", "k", connected);
    vi.setSystemTime(59_999);
    expect(getCachedProbe("p", "k")).toEqual(connected);
    vi.setSystemTime(60_001);
    expect(getCachedProbe("p", "k")).toBeNull();
  });

  it("expires unreachable entries after 10s", () => {
    vi.useFakeTimers();
    vi.setSystemTime(0);
    setCachedProbe("p", "k", unreachable);
    vi.setSystemTime(10_001);
    expect(getCachedProbe("p", "k")).toBeNull();
  });

  it("invalidateProbe drops the entry", () => {
    setCachedProbe("p", "k", connected);
    invalidateProbe("p", "k");
    expect(getCachedProbe("p", "k")).toBeNull();
  });
});

/**
 * Page-level browser primitives the MCP tools wrap.
 *
 * Each function takes a Playwright Page and a small typed opts payload,
 * runs the action with sensible defaults, and returns a normalized result.
 * Keeping the action layer separate from the MCP tool layer means the
 * tools can stay one-screen each (zod schema + handler) and these can be
 * unit-tested without any MCP envelope plumbing.
 *
 * Snapshot format: V1 returns a flat list of interactable elements with
 * stable ref ids (e1, e2, ...) scoped to the snapshot call. This matches
 * Hermes' agent-browser ref convention so agent prompts can reuse the
 * same mental model. The full Playwright aria tree comes in V1.1.
 */
import type { Page } from "playwright-core";

export interface NavigateOptions {
  url: string;
  waitUntil?: "load" | "domcontentloaded" | "networkidle" | "commit";
  timeoutMs?: number;
}

export interface NavigateResult {
  url: string;
  title: string;
}

export async function navigate(page: Page, opts: NavigateOptions): Promise<NavigateResult> {
  await page.goto(opts.url, {
    waitUntil: opts.waitUntil ?? "load",
    timeout: opts.timeoutMs ?? 30_000,
  });
  return {
    url: page.url(),
    title: await page.title().catch(() => ""),
  };
}

export interface SnapshotElement {
  /** Ref id stable within this snapshot, e.g. "e1". */
  ref: string;
  /** ARIA role or tag name. */
  role: string;
  /** Accessible name when available, else trimmed text. */
  name: string;
  /** Empty for buttons/links; populated for inputs/selects. */
  value?: string;
  /** True when disabled / aria-disabled. */
  disabled?: boolean;
  /** href for links so agents can decide whether to navigate directly. */
  href?: string;
}

export interface SnapshotResult {
  url: string;
  title: string;
  elements: SnapshotElement[];
  /** Truncated text content of the page, for context. */
  text: string;
}

const SNAPSHOT_ELEMENT_LIMIT = 200;
const SNAPSHOT_TEXT_CHAR_LIMIT = 8_000;

/**
 * Build a flat list of interactable elements + a text excerpt.
 *
 * We evaluate in the page rather than using Playwright's role queries
 * because we want a single round-trip that returns everything we need:
 * role, accessible name, current value, href, and a temporary numbered
 * attribute we hang off each element so subsequent click/type calls can
 * resolve back to the same DOM node via [data-notfair-ref="eN"].
 */
export async function snapshot(page: Page): Promise<SnapshotResult> {
  const { url, title, elements, text } = await page.evaluate(
    ({ elemLimit, textLimit }) => {
      const REF_ATTR = "data-notfair-ref";
      // Clear stale refs from a previous snapshot.
      for (const stale of Array.from(document.querySelectorAll(`[${REF_ATTR}]`))) {
        stale.removeAttribute(REF_ATTR);
      }

      const SELECTOR = [
        "a[href]",
        "button",
        "input:not([type=hidden])",
        "select",
        "textarea",
        "[role=button]",
        "[role=link]",
        "[role=checkbox]",
        "[role=radio]",
        "[role=tab]",
        "[role=menuitem]",
        "[contenteditable=true]",
      ].join(",");

      const isVisible = (el: Element): boolean => {
        const rect = (el as HTMLElement).getBoundingClientRect();
        if (rect.width === 0 || rect.height === 0) return false;
        const style = window.getComputedStyle(el as HTMLElement);
        return style.visibility !== "hidden" && style.display !== "none";
      };

      const accessibleName = (el: Element): string => {
        const aria = el.getAttribute("aria-label");
        if (aria) return aria;
        const labelled = el.getAttribute("aria-labelledby");
        if (labelled) {
          const node = document.getElementById(labelled);
          if (node?.textContent) return node.textContent.trim();
        }
        if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
          const id = el.getAttribute("id");
          if (id) {
            const label = document.querySelector(`label[for="${CSS.escape(id)}"]`);
            if (label?.textContent) return label.textContent.trim();
          }
          if (el.placeholder) return el.placeholder;
        }
        const text = (el as HTMLElement).innerText ?? el.textContent ?? "";
        return text.trim().slice(0, 200);
      };

      const out: Array<Record<string, unknown>> = [];
      let counter = 0;
      const nodes = Array.from(document.querySelectorAll(SELECTOR)).filter(isVisible);
      for (const el of nodes) {
        if (counter >= elemLimit) break;
        counter++;
        const ref = `e${counter}`;
        el.setAttribute(REF_ATTR, ref);

        const tag = el.tagName.toLowerCase();
        const role = el.getAttribute("role") ?? tag;
        const item: Record<string, unknown> = {
          ref,
          role,
          name: accessibleName(el),
        };
        if (el instanceof HTMLAnchorElement && el.href) item.href = el.href;
        if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
          item.value = el.value;
        }
        if ((el as HTMLButtonElement).disabled || el.getAttribute("aria-disabled") === "true") {
          item.disabled = true;
        }
        out.push(item);
      }

      const rawText = document.body?.innerText ?? "";
      const text = rawText.slice(0, textLimit);

      return {
        url: window.location.href,
        title: document.title,
        elements: out,
        text,
      };
    },
    { elemLimit: SNAPSHOT_ELEMENT_LIMIT, textLimit: SNAPSHOT_TEXT_CHAR_LIMIT },
  );
  return { url, title, elements: elements as unknown as SnapshotElement[], text };
}

function refSelector(ref: string): string {
  // CSS attribute selectors don't need escaping for our ref format (eN).
  if (!/^e\d+$/.test(ref)) {
    throw new Error(`Invalid ref "${ref}" — expected "e<number>"`);
  }
  return `[data-notfair-ref="${ref}"]`;
}

export interface ClickOptions {
  ref: string;
  button?: "left" | "right" | "middle";
  modifiers?: ("Alt" | "Control" | "Meta" | "Shift")[];
  doubleClick?: boolean;
  timeoutMs?: number;
}

export async function click(page: Page, opts: ClickOptions): Promise<void> {
  const locator = page.locator(refSelector(opts.ref));
  const timeout = opts.timeoutMs ?? 10_000;
  if (opts.doubleClick) {
    await locator.dblclick({ button: opts.button, modifiers: opts.modifiers, timeout });
  } else {
    await locator.click({ button: opts.button, modifiers: opts.modifiers, timeout });
  }
}

export interface TypeOptions {
  ref: string;
  text: string;
  /** Press Enter after typing. */
  submit?: boolean;
  /** Clear the field before typing. Default: true. */
  clearFirst?: boolean;
  timeoutMs?: number;
}

export async function type(page: Page, opts: TypeOptions): Promise<void> {
  const locator = page.locator(refSelector(opts.ref));
  const timeout = opts.timeoutMs ?? 10_000;
  if (opts.clearFirst !== false) {
    await locator.fill("", { timeout });
  }
  await locator.fill(opts.text, { timeout });
  if (opts.submit) {
    await locator.press("Enter", { timeout });
  }
}

export interface PressOptions {
  /** Playwright key string, e.g. "Enter", "Tab", "Control+a". */
  key: string;
  /** Optional ref to focus before pressing. If omitted, presses at page level. */
  ref?: string;
  timeoutMs?: number;
}

export async function press(page: Page, opts: PressOptions): Promise<void> {
  const timeout = opts.timeoutMs ?? 10_000;
  if (opts.ref) {
    const locator = page.locator(refSelector(opts.ref));
    await locator.press(opts.key, { timeout });
  } else {
    await page.keyboard.press(opts.key);
  }
}

export interface ScrollOptions {
  direction: "up" | "down" | "left" | "right";
  /** Pixels. Default: 600 (one screen-ish on most viewports). */
  amount?: number;
}

export async function scroll(page: Page, opts: ScrollOptions): Promise<void> {
  const amount = opts.amount ?? 600;
  const dx =
    opts.direction === "left" ? -amount : opts.direction === "right" ? amount : 0;
  const dy =
    opts.direction === "up" ? -amount : opts.direction === "down" ? amount : 0;
  await page.evaluate(({ x, y }) => window.scrollBy(x, y), { x: dx, y: dy });
}

export async function back(page: Page): Promise<void> {
  await page.goBack({ waitUntil: "load" }).catch(() => {});
}

"use server";

import { randomBytes, createHash } from "node:crypto";
import { revalidatePath } from "next/cache";
import { headers } from "next/headers";
import { getActiveProject } from "@/server/active-project";
import { isPresetKey, mcpSpecByKey } from "@/server/mcp-catalog";
import { setPending } from "@/server/mcp-pending";
import { disconnectMcp as runDisconnect } from "@/server/mcp/state";
import {
  insertUserMcpServer,
  findUserMcpServer,
  findUserMcpServerByResourceUrl,
  deleteUserMcpServer,
} from "@/server/db/user-mcp-servers";
import { slugify } from "@/lib/slug";
import { deriveDiscoveryUrl } from "@/server/mcp/discovery-url";

export type StartMcpConnectResult =
  | { ok: true; authorize_url: string }
  | { ok: false; error: string };

/**
 * Begin a one-click MCP OAuth flow. Server-side: discovery → DCR →
 * PKCE-pair → pending-state stash → caller redirects browser to the
 * authorize URL we return. The callback handler in
 * `/api/mcp-oauth/callback` finishes the exchange + writes the harness
 * mcp config.
 */
export async function startMcpConnect(input: {
  mcp_key: string;
  /**
   * Same-origin path to bounce back to after the callback. Anything that
   * doesn't look like a local path (no leading `/`, or `//` protocol-relative)
   * is dropped — the callback will use the default `/connections` instead.
   */
  return_to?: string;
}): Promise<StartMcpConnectResult> {
  const project = await getActiveProject();
  if (!project) {
    return { ok: false, error: "No active project. Pick one before connecting an MCP." };
  }

  const spec = mcpSpecByKey(project.slug, input.mcp_key);
  if (!spec) return { ok: false, error: `Unknown MCP key: ${input.mcp_key}` };

  let resolved: ResolvedAuthServer;
  try {
    resolved = await resolveAuthServer(spec.discovery_url);
  } catch (err) {
    return { ok: false, error: `Discovery failed: ${humanError(err)}` };
  }

  const origin = await originFromIncomingRequest();
  const redirect_uri = `${origin}/api/mcp-oauth/callback`;

  const auth_method = pickClientAuthMethod(
    resolved.token_endpoint_auth_methods_supported,
  );
  let dcr: DcrResponse;
  try {
    dcr = await dynamicRegister(
      resolved.registration_endpoint,
      redirect_uri,
      auth_method,
    );
  } catch (err) {
    return { ok: false, error: `Registration failed: ${humanError(err)}` };
  }

  // PKCE — S256 challenge from a 64-byte verifier.
  const code_verifier = base64url(randomBytes(64));
  const code_challenge = base64url(
    createHash("sha256").update(code_verifier).digest(),
  );
  const state = base64url(randomBytes(24));

  setPending(state, {
    catalog_key: spec.key,
    display_name: spec.display_name,
    resource_url: spec.resource_url,
    issuer: resolved.issuer,
    token_endpoint: resolved.token_endpoint,
    client_id: dcr.client_id,
    client_secret: dcr.client_secret,
    code_verifier,
    redirect_uri,
    project_slug: project.slug,
    return_to: sanitizeReturnTo(input.return_to),
    created_at: Date.now(),
  });

  const u = new URL(resolved.authorization_endpoint);
  u.searchParams.set("response_type", "code");
  u.searchParams.set("client_id", dcr.client_id);
  u.searchParams.set("redirect_uri", redirect_uri);
  u.searchParams.set("code_challenge", code_challenge);
  u.searchParams.set("code_challenge_method", "S256");
  u.searchParams.set("state", state);
  u.searchParams.set("resource", spec.resource_url);

  return { ok: true, authorize_url: u.toString() };
}

export async function disconnectMcpAction(input: {
  mcp_key: string;
}): Promise<{ ok: true } | { ok: false; error: string }> {
  const project = await getActiveProject();
  if (!project) {
    return { ok: false, error: "No active project to disconnect from." };
  }
  try {
    await runDisconnect(project.slug, input.mcp_key);
  } catch (err) {
    return { ok: false, error: humanError(err) };
  }
  revalidatePath("/", "layout");
  return { ok: true };
}

/**
 * Fetch the tool list for an external (OAuth-connected) MCP. Driven by the
 * tools modal on the Connections page — lazy on dialog-open so we don't
 * pay the RPC roundtrip when the user is just glancing at the page.
 *
 * Probes the MCP's tools/list endpoint with the stored bearer, then
 * normalizes each entry into the same ToolSummary shape we ship for
 * built-in tools — the modal renders both identically.
 */
export async function listMcpToolsAction(input: {
  mcp_key: string;
}): Promise<
  | { ok: true; tools: import("@/server/mcp-server/tool-summaries").ToolSummary[] }
  | { ok: false; error: string }
> {
  const project = await getActiveProject();
  if (!project) {
    return { ok: false, error: "No active project." };
  }
  const { getMcpConfig, mcpRpcAutoRefresh } = await import("@/server/mcp/rpc");
  const cfg = getMcpConfig(project.slug, input.mcp_key);
  if (!cfg) {
    return { ok: false, error: "MCP is not configured for this project." };
  }
  const r = await mcpRpcAutoRefresh<{
    tools?: Array<{ name?: unknown; description?: unknown; inputSchema?: unknown }>;
  }>(project.slug, input.mcp_key, "tools/list", {}, { timeoutMs: 5_000 });
  if (!r.ok) {
    const message =
      r.kind === "http_error"
        ? `HTTP ${r.status}`
        : r.kind === "rpc_error"
          ? `RPC ${r.code}: ${r.message}`
          : r.kind === "timeout"
            ? "MCP call timed out"
            : r.kind === "aborted"
              ? "MCP call aborted"
              : r.kind === "malformed_response"
                ? r.message
                : r.message;
    return { ok: false, error: message };
  }
  const { argsFromJsonSchema } = await import("@/server/mcp-server/tool-summaries");
  const tools = Array.isArray(r.result?.tools)
    ? r.result.tools
        .filter(
          (
            t,
          ): t is { name: string; description?: string; inputSchema?: Record<string, unknown> } =>
            typeof t?.name === "string",
        )
        .map((t) => ({
          name: t.name,
          description: typeof t.description === "string" ? t.description : "",
          args:
            t.inputSchema && typeof t.inputSchema === "object"
              ? argsFromJsonSchema(t.inputSchema)
              : [],
        }))
    : [];
  return { ok: true, tools };
}

export type ProbeMcpDiscoveryResult =
  | {
      ok: true;
      discovery_url: string;
      issuer: string;
      registration_endpoint: string;
    }
  | { ok: false; error: string; kind: ProbeFailureKind };

type ProbeFailureKind =
  | "bad_url"
  | "no_discovery_doc"
  | "no_authorization_servers"
  | "as_metadata_missing_endpoints"
  | "dcr_unsupported";

/**
 * Validate that a candidate MCP resource URL is OAuth-2.0 connectable.
 *
 * Derives the RFC 9728 discovery URL from the resource URL, fetches it,
 * follows the first `authorization_servers` issuer, fetches its RFC 8414
 * metadata, and asserts the AS publishes a `registration_endpoint` (DCR).
 *
 * Returns the resolved discovery URL on success so the caller can stash
 * it on the user_mcp_servers row — the connect flow reuses that URL
 * verbatim, so we don't re-derive it later.
 */
export async function probeMcpDiscovery(input: {
  resource_url: string;
}): Promise<ProbeMcpDiscoveryResult> {
  const discovery_url = deriveDiscoveryUrl(input.resource_url);
  if (!discovery_url) {
    return {
      ok: false,
      kind: "bad_url",
      error: "Resource URL must be an https URL.",
    };
  }
  try {
    const resolved = await resolveAuthServer(discovery_url);
    return {
      ok: true,
      discovery_url,
      issuer: resolved.issuer,
      registration_endpoint: resolved.registration_endpoint,
    };
  } catch (err) {
    return classifyProbeError(err);
  }
}

export type AddUserMcpServerResult =
  | { ok: true; key: string }
  | { ok: false; error: string; kind: AddFailureKind };

type AddFailureKind = ProbeFailureKind | "no_project" | "name_unusable";

const KEY_PATTERN = /^[a-z0-9][a-z0-9-]*$/;

/**
 * Register an MCP server for the active project — idempotent.
 *
 *  - If `key` matches a preset (e.g. `notfair-googleads`), the action
 *    only ensures the key is *unhidden* (clears the per-project
 *    hide-list). No row is written; the preset entry surfaces again via
 *    `getMcpCatalog`.
 *  - If a `user_mcp_servers` row for the key already exists, the action
 *    is a no-op success — used by Browse-connectors so re-clicking a
 *    tile after a canceled OAuth simply re-runs `startMcpConnect`
 *    instead of erroring on "already exists".
 *  - Otherwise probes RFC 9728 discovery + DCR; on success, inserts a
 *    new `user_mcp_servers` row.
 *
 * `key` accepts a stable preset/connector identifier to bypass
 * slugification (e.g. Browse passes `notfair-googleads` directly so it
 * matches the preset key rather than `slugify("NotFair Google Ads")` =
 * `notfair-google-ads`). When omitted, the display name is slugified.
 */
export async function addUserMcpServerAction(input: {
  display_name: string;
  description?: string;
  resource_url: string;
  /** Optional canonical key override (used by Browse connectors). */
  key?: string;
}): Promise<AddUserMcpServerResult> {
  const project = await getActiveProject();
  if (!project) {
    return {
      ok: false,
      kind: "no_project",
      error: "No active project. Pick one before adding an MCP server.",
    };
  }

  let key: string;
  if (input.key && KEY_PATTERN.test(input.key)) {
    key = input.key;
  } else {
    const slug = slugify(input.display_name);
    if (!slug.ok) {
      return {
        ok: false,
        kind: "name_unusable",
        error: `Can't derive a key from this name: ${slug.reason}.`,
      };
    }
    key = slug.slug;
  }

  // Preset re-add: just un-hide. No row to write, no discovery probe.
  if (isPresetKey(key)) {
    const { removeHiddenMcpPresetKey } = await import("@/server/db/projects");
    removeHiddenMcpPresetKey(project.slug, key);
    revalidatePath("/", "layout");
    return { ok: true, key };
  }

  // User row already exists for this key — Browse "click again" path.
  if (findUserMcpServer(project.slug, key)) {
    return { ok: true, key };
  }

  // Same MCP server (same URL) is already in this project under a
  // different key — e.g. NotFair Meta Ads was added pre-canonical-id and
  // saved as `notfair-meta-ads`, while the tile click would use
  // `notfair-metaads`. Treat as an idempotent re-pick: return the
  // existing key so the connect chain reuses it instead of writing a
  // duplicate row.
  const existingByUrl = findUserMcpServerByResourceUrl(
    project.slug,
    input.resource_url,
  );
  if (existingByUrl) {
    return { ok: true, key: existingByUrl.key };
  }

  const probe = await probeMcpDiscovery({ resource_url: input.resource_url });
  if (!probe.ok) return probe;
  insertUserMcpServer({
    project_slug: project.slug,
    key,
    display_name: input.display_name.trim(),
    description: input.description?.trim() ?? "",
    resource_url: input.resource_url.trim(),
    discovery_url: probe.discovery_url,
  });
  revalidatePath("/", "layout");
  return { ok: true, key };
}

/**
 * Remove an MCP server from the active project. Works on both presets
 * and user rows:
 *
 *  - Preset: appends the key to `projects.hidden_mcp_preset_keys_json`
 *    so `getMcpCatalog` filters it out from now on. Token + adapter
 *    cleanup runs the same way.
 *  - User row: deletes the `user_mcp_servers` row.
 *
 * Either path also drops the stored bearer and unregisters from every
 * agent's harness config.
 */
export async function removeUserMcpServerAction(input: {
  mcp_key: string;
}): Promise<{ ok: true } | { ok: false; error: string }> {
  const project = await getActiveProject();
  if (!project) {
    return { ok: false, error: "No active project." };
  }
  const isPreset = isPresetKey(input.mcp_key);
  if (!isPreset) {
    const row = findUserMcpServer(project.slug, input.mcp_key);
    if (!row) {
      return { ok: false, error: `Unknown MCP key: ${input.mcp_key}.` };
    }
  }
  try {
    await runDisconnect(project.slug, input.mcp_key);
    const { listProjectAgents } = await import("@/server/agent-meta");
    const { getProject, addHiddenMcpPresetKey } = await import(
      "@/server/db/projects"
    );
    const { requireAdapter } = await import("@/server/adapters/registry");
    const proj = getProject(project.slug);
    if (proj) {
      const adapter = requireAdapter(proj.harness_adapter);
      const agents = await listProjectAgents(project.slug);
      for (const agent of agents) {
        try {
          await adapter.unregisterMcp({
            serverName: input.mcp_key,
            projectSlug: project.slug,
            agentId: agent.agent_id,
          });
        } catch {
          // best-effort
        }
      }
    }
    if (isPreset) {
      addHiddenMcpPresetKey(project.slug, input.mcp_key);
    } else {
      deleteUserMcpServer(project.slug, input.mcp_key);
    }
  } catch (err) {
    return { ok: false, error: humanError(err) };
  }
  revalidatePath("/", "layout");
  return { ok: true };
}

// ─── helpers ────────────────────────────────────────────────────────

type ResolvedAuthServer = {
  issuer: string;
  authorization_endpoint: string;
  token_endpoint: string;
  registration_endpoint: string;
  /**
   * The AS's advertised auth methods for the token endpoint. Drives DCR
   * registration: we prefer the public-PKCE `none` method when the AS
   * supports it (MCP spec default), and fall back to `client_secret_post`
   * for servers like Supabase that don't accept public clients.
   */
  token_endpoint_auth_methods_supported: string[];
};

type ClientAuthMethod = "none" | "client_secret_post";

class ProbeError extends Error {
  kind: ProbeFailureKind;
  constructor(kind: ProbeFailureKind, message: string) {
    super(message);
    this.kind = kind;
  }
}

async function resolveAuthServer(
  resourceDiscoveryUrl: string,
): Promise<ResolvedAuthServer> {
  // RFC 9728: GET .well-known/oauth-protected-resource → carries the
  // `authorization_servers` array. We pick the first and then fetch its
  // RFC 8414 AS metadata to learn registration/token/authorize endpoints.
  let r1: unknown;
  try {
    r1 = await fetchJson(resourceDiscoveryUrl, 8000);
  } catch (err) {
    throw new ProbeError(
      "no_discovery_doc",
      err instanceof Error ? err.message : String(err),
    );
  }
  const servers = (r1 as { authorization_servers?: unknown }).authorization_servers;
  if (!Array.isArray(servers) || servers.length === 0) {
    throw new ProbeError(
      "no_authorization_servers",
      "no authorization_servers in discovery doc",
    );
  }
  const issuer = String(servers[0]).replace(/\/$/, "");
  // RFC 8414 §3.1 says the well-known suffix is inserted between the
  // issuer's host and path (the "inserted" form). The OIDC Discovery and
  // some MCP servers also accept the issuer-suffix variant ("appended"
  // form). Try each in order until one returns valid metadata.
  const candidates = asMetadataCandidates(issuer);
  const attempts: string[] = [];
  let meta: Partial<ResolvedAuthServer> | null = null;
  for (const url of candidates) {
    attempts.push(url);
    try {
      meta = (await fetchJson(url, 8000)) as Partial<ResolvedAuthServer>;
      break;
    } catch {
      // try the next candidate
    }
  }
  if (!meta) {
    throw new ProbeError(
      "as_metadata_missing_endpoints",
      `Couldn't fetch AS metadata. Tried: ${attempts.join(", ")}`,
    );
  }
  if (!meta.authorization_endpoint || !meta.token_endpoint) {
    throw new ProbeError(
      "as_metadata_missing_endpoints",
      "AS metadata missing authorize/token endpoints",
    );
  }
  if (!meta.registration_endpoint) {
    throw new ProbeError(
      "dcr_unsupported",
      "AS metadata is missing registration_endpoint — dynamic client registration is required.",
    );
  }
  const advertised = (meta as Record<string, unknown>)
    .token_endpoint_auth_methods_supported;
  return {
    issuer,
    authorization_endpoint: meta.authorization_endpoint,
    token_endpoint: meta.token_endpoint,
    registration_endpoint: meta.registration_endpoint,
    token_endpoint_auth_methods_supported: Array.isArray(advertised)
      ? advertised.filter((s): s is string => typeof s === "string")
      : [],
  };
}

/**
 * Pick a token-endpoint auth method that the AS supports AND we know
 * how to drive at the callback. We prefer `none` (PKCE-only, MCP-spec
 * default); when the AS doesn't advertise it (Supabase, some OIDC
 * providers) we fall back to `client_secret_post`. `client_secret_basic`-
 * only servers aren't supported — the callback's token exchange sends
 * the secret in the POST body, not the Authorization header.
 */
function pickClientAuthMethod(supported: string[]): ClientAuthMethod {
  if (supported.length === 0) return "none";
  if (supported.includes("none")) return "none";
  return "client_secret_post";
}

/**
 * Build the AS-metadata URLs to probe, in priority order, for a given
 * issuer. The "inserted" variants are spec-correct (RFC 8414 §3.1 / OIDC
 * Discovery §4); the "appended" variants are a common deviation a number
 * of real-world MCP servers still ship — including, ironically, the
 * issuer URL Stripe advertises (`https://access.stripe.com/mcp`), which
 * resolves only via the inserted form.
 */
function asMetadataCandidates(issuer: string): string[] {
  const out: string[] = [];
  let u: URL;
  try {
    u = new URL(issuer);
  } catch {
    return out;
  }
  const path = u.pathname === "/" ? "" : u.pathname.replace(/\/+$/, "");
  const origin = u.origin;
  // RFC 8414: inserted between host and path.
  out.push(`${origin}/.well-known/oauth-authorization-server${path}`);
  // OIDC Discovery: same insertion shape with a different suffix.
  out.push(`${origin}/.well-known/openid-configuration${path}`);
  // Appended-form fallbacks for servers that don't follow the insertion
  // rule. Only worth trying when the issuer has a non-root path; for a
  // root issuer the appended form equals the inserted form.
  if (path) {
    out.push(`${issuer.replace(/\/$/, "")}/.well-known/oauth-authorization-server`);
    out.push(`${issuer.replace(/\/$/, "")}/.well-known/openid-configuration`);
  }
  return out;
}

function classifyProbeError(err: unknown): ProbeMcpDiscoveryResult {
  if (err instanceof ProbeError) {
    return { ok: false, kind: err.kind, error: err.message };
  }
  return {
    ok: false,
    kind: "no_discovery_doc",
    error: err instanceof Error ? err.message : String(err),
  };
}

type DcrResponse = {
  client_id: string;
  client_secret?: string;
  token_endpoint_auth_method?: string;
};

async function dynamicRegister(
  registration_endpoint: string,
  redirect_uri: string,
  auth_method: ClientAuthMethod,
): Promise<DcrResponse> {
  // PKCE-only `none` is the MCP-spec default for public clients. Some
  // OAuth servers (Supabase, certain OIDC providers) reject `none` and
  // require a confidential client; for those we register as
  // `client_secret_post` — the AS returns a client_secret which the
  // callback then sends alongside the code at token exchange.
  //
  // grant_types includes `refresh_token` per SEP-2207 ("OIDC-Flavored
  // Refresh Token Guidance", accepted 2026-02-04). Some Authorization
  // Servers (notably Stripe's MCP) only issue refresh tokens to clients
  // that explicitly register the capability — without this we still get
  // a working access token but the user is forced to reconnect when it
  // expires (~1h for Stripe). Servers that don't support refresh_token
  // grant either ignore the extra entry or reject it; in the latter case
  // we'd fall back to the authorization_code-only registration anyway.
  const body = {
    client_name: "NotFair",
    redirect_uris: [redirect_uri],
    grant_types: ["authorization_code", "refresh_token"],
    response_types: ["code"],
    token_endpoint_auth_method: auth_method,
  };
  const res = await fetch(registration_endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`DCR ${res.status}: ${text.slice(0, 200)}`);
  }
  const json = (await res.json()) as DcrResponse;
  if (!json.client_id) throw new Error("DCR response missing client_id");
  return json;
}

async function fetchJson(url: string, timeout_ms: number): Promise<unknown> {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), timeout_ms);
  try {
    const res = await fetch(url, { signal: ctl.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status} from ${url}`);
    return await res.json();
  } finally {
    clearTimeout(t);
  }
}

function base64url(b: Buffer): string {
  return b.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function originFromIncomingRequest(): Promise<string> {
  const h = await headers();
  // Next surfaces forwarded headers when behind a proxy; fall back to host.
  const proto = h.get("x-forwarded-proto") ?? "http";
  const rawHost = h.get("x-forwarded-host") ?? h.get("host");
  if (!rawHost) {
    throw new Error("Could not derive origin from request headers");
  }
  // RFC 8252 §7.3 says native OAuth clients use the loopback IP (127.0.0.1)
  // rather than the `localhost` hostname; some providers (Vercel) enforce
  // this and reject `http://localhost` as an "invalid redirect URL".
  // Normalize so the registered + exchanged redirect URI is loopback-IP
  // regardless of which form the user typed into the address bar.
  const host = rawHost.replace(/^localhost(:|$)/, "127.0.0.1$1");
  return `${proto}://${host}`;
}

function humanError(err: unknown): string {
  if (err instanceof Error) return err.message;
  return String(err);
}

/**
 * Accept only same-origin, path-only redirect targets. Anything with a scheme
 * or a `//` prefix would let a caller redirect the user off-site after OAuth,
 * which is an open-redirect class bug. Returns undefined when the input
 * isn't a safe local path, so the callback falls back to /connections.
 */
function sanitizeReturnTo(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  if (!raw.startsWith("/")) return undefined;
  if (raw.startsWith("//")) return undefined;
  return raw;
}

"use server";

import { cloneAgent } from "@/server/agents/clone";
import { cascadeDeleteAgentArtifacts } from "@/server/agents/cascade-delete";
import { writeAgentMeta } from "@/server/agent-meta";

// --- Relocate (used by project rename to move agents to the new slug) ---

export type RelocateAgentInput = {
  old_agent_id: string;
  source_project_slug: string;
  new_project_slug: string;
  new_slug: string;
  new_display_name: string;
  preserve_source_agent_id?: string;
  preserve_created_at?: string;
};

export type RelocateAgentResult = {
  new_agent_id: string;
  new_slug: string;
};

export async function relocateAgent(
  input: RelocateAgentInput,
): Promise<RelocateAgentResult> {
  const cloneResult = await cloneAgent({
    source_agent_id: input.old_agent_id,
    project_slug: input.new_project_slug,
    new_slug: input.new_slug,
    display_name: input.new_display_name,
    slug_is_canonical: true,
  });

  await writeAgentMeta({
    agent_id: cloneResult.new_agent_id,
    project_slug: input.new_project_slug,
    slug: cloneResult.new_slug,
    name: input.new_display_name,
    ...(input.preserve_source_agent_id
      ? { source_agent_id: input.preserve_source_agent_id }
      : {}),
    created_at: input.preserve_created_at ?? new Date().toISOString(),
  });

  // Best-effort: the clone already succeeded, so a cleanup failure must not
  // fail the relocation — but it must not be invisible either (a silent
  // swallow here previously masked cleanup breaking entirely, stranding the
  // old agent's sessions and MCP registrations).
  await cascadeDeleteAgentArtifacts(
    input.source_project_slug,
    input.old_agent_id,
  ).catch((err) =>
    console.error(`[relocate] cleanup of old agent ${input.old_agent_id} failed:`, err),
  );

  return {
    new_agent_id: cloneResult.new_agent_id,
    new_slug: cloneResult.new_slug,
  };
}

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { randomBytes, timingSafeEqual } from "node:crypto";

/**
 * Shared secret used to authenticate calls from harness-side agents into our
 * outbound-facing MCP server. Lives in a file with 0600 perms inside the
 * NotFair data dir (NOT the project SQLite DB — keeping it in a small
 * dedicated file lets the file's own mode bits enforce single-user access
 * and lets registration read it with a one-liner).
 *
 * Single-user local CLI: we mint one secret per install and reuse it across
 * every project + every agent. No rotation in V1 — easy to add later by
 * deleting the file and re-running `NotFair mcp register`.
 */

const DATA_DIR = process.env.NOTFAIR_DATA_DIR ?? join(homedir(), ".notfair");
const SECRET_PATH = join(DATA_DIR, "mcp-server-secret");

/** Read the secret, minting + persisting one the first time. */
export function getOrCreateMcpServerSecret(): string {
  if (!existsSync(DATA_DIR)) {
    mkdirSync(DATA_DIR, { recursive: true, mode: 0o700 });
  }
  if (existsSync(SECRET_PATH)) {
    const value = readFileSync(SECRET_PATH, "utf8").trim();
    if (value) return value;
  }
  const minted = randomBytes(32).toString("hex");
  writeFileSync(SECRET_PATH, `${minted}\n`, { mode: 0o600 });
  return minted;
}

/**
 * Constant-time compare of a presented bearer against the stored secret.
 * Returns false rather than throwing when the input is malformed so callers
 * can map all unauth paths to 401 without special-casing exceptions.
 */
export function verifyMcpServerSecret(presented: string | null | undefined): boolean {
  if (!presented) return false;
  const expected = getOrCreateMcpServerSecret();
  if (presented.length !== expected.length) return false;
  return timingSafeEqual(
    Buffer.from(presented, "utf8"),
    Buffer.from(expected, "utf8"),
  );
}

/** Where the secret lives on disk — surfaced for CLI registration helpers. */
export function getMcpServerSecretPath(): string {
  return SECRET_PATH;
}

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";
import { getMasterKey } from "./master-key";

const ALGORITHM = "aes-256-gcm";
const IV_LEN = 12;
const TAG_LEN = 16;

/**
 * Encrypt a plaintext string with AES-256-GCM using the project master key
 * (loaded from OS keychain). Output format: base64(iv | ciphertext | tag).
 */
export async function encrypt(plaintext: string): Promise<string> {
  const key = await getMasterKey();
  const iv = randomBytes(IV_LEN);
  const cipher = createCipheriv(ALGORITHM, key, iv);
  const encrypted = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, encrypted, tag]).toString("base64");
}

export async function decrypt(blob: string): Promise<string> {
  const key = await getMasterKey();
  const buf = Buffer.from(blob, "base64");
  if (buf.length < IV_LEN + TAG_LEN) throw new Error("Encrypted blob is malformed");
  const iv = buf.subarray(0, IV_LEN);
  const tag = buf.subarray(buf.length - TAG_LEN);
  const ciphertext = buf.subarray(IV_LEN, buf.length - TAG_LEN);
  const decipher = createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(tag);
  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return decrypted.toString("utf8");
}

import { NextResponse } from "next/server";
import { consumePending } from "@/server/mcp-pending";
import { setMcpBearer } from "@/server/mcp/state";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * OAuth 2.0 redirect URI for the one-click MCP connect flow. The browser
 * lands here after the user authorizes upstream. We look up the pending
 * flow by `state`, exchange the code for an access token, write the
 * harness MCP config, and bounce the user back to the
 * agent's MCP tab.
 *
 * On failure we still redirect (so the browser doesn't end up on a raw
 * JSON page); the destination carries `?mcp_error=…` for the page to
 * surface. The pending entry is always consumed.
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  const state = url.searchParams.get("state");
  const upstreamError = url.searchParams.get("error");

  if (!state) {
    return htmlErrorPage("Missing state parameter; cannot resume the OAuth flow.");
  }

  const pending = consumePending(state);
  if (!pending) {
    return htmlErrorPage("This authorization link has expired or was already used.");
  }

  // The pending state may carry a `return_to` (e.g. the chat URL the user
  // started from). Default to / so the root redirect bounces them to their
  // active project's home if no caller asked for a specific destination.
  // `return_to` is already sanitized in startMcpConnect to be a same-origin
  // path; URL() with a base will additionally reject anything malformed.
  const back = new URL(pending.return_to ?? "/", request.url);

  if (upstreamError) {
    back.searchParams.set(
      "mcp_error",
      `Authorization rejected: ${upstreamError}`,
    );
    return NextResponse.redirect(back);
  }
  if (!code) {
    back.searchParams.set("mcp_error", "Authorization callback returned no code.");
    return NextResponse.redirect(back);
  }

  // Token exchange. Send PKCE + (defensively) the secret. Servers that
  // honor token_endpoint_auth_method=none ignore the secret; servers that
  // require it still accept this request. Either way PKCE is validated.
  const body = new URLSearchParams({
    grant_type: "authorization_code",
    code,
    client_id: pending.client_id,
    redirect_uri: pending.redirect_uri,
    code_verifier: pending.code_verifier,
    resource: pending.resource_url,
  });
  if (pending.client_secret) body.set("client_secret", pending.client_secret);

  let tokenEnvelope: {
    access_token: string;
    refresh_token?: string;
    expires_in?: number;
    scope?: string;
  };
  try {
    const res = await fetch(pending.token_endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body: body.toString(),
    });
    const text = await res.text();
    if (!res.ok) {
      back.searchParams.set(
        "mcp_error",
        `Token exchange failed (HTTP ${res.status}): ${truncate(text, 200)}`,
      );
      return NextResponse.redirect(back);
    }
    const parsed = JSON.parse(text) as {
      access_token?: string;
      refresh_token?: string;
      expires_in?: number;
      scope?: string;
    };
    if (!parsed.access_token) {
      back.searchParams.set("mcp_error", "Token endpoint returned no access_token.");
      return NextResponse.redirect(back);
    }
    tokenEnvelope = {
      access_token: parsed.access_token,
      refresh_token: parsed.refresh_token,
      expires_in: parsed.expires_in,
      scope: parsed.scope,
    };
  } catch (err) {
    back.searchParams.set(
      "mcp_error",
      `Token exchange error: ${err instanceof Error ? err.message : String(err)}`,
    );
    return NextResponse.redirect(back);
  }

  // Compute absolute expiry only when the provider advertised expires_in.
  // For providers that omit it (rare, but legal under RFC 6749), we leave
  // expires_at NULL and rely on reactive refresh-on-401.
  const expires_at =
    typeof tokenEnvelope.expires_in === "number"
      ? new Date(Date.now() + tokenEnvelope.expires_in * 1000).toISOString()
      : undefined;

  try {
    await setMcpBearer(
      pending.project_slug,
      pending.catalog_key,
      tokenEnvelope.access_token,
      {
        refresh_token: tokenEnvelope.refresh_token,
        expires_at,
        scope: tokenEnvelope.scope,
        // Stash everything the refresh helper needs so it can rotate the
        // access token later without bouncing through consent again.
        token_endpoint: pending.token_endpoint,
        client_id: pending.client_id,
        client_secret: pending.client_secret,
      },
    );
  } catch (err) {
    const raw = err instanceof Error ? err.message : String(err);
    // Scrub bearers + any oat_ token shape before exposing in the URL —
    // the redirect lands in browser history, server logs, and Referer
    // headers on the destination page. Leaking the access token there
    // would let any local-machine reader replay calls against the MCP.
    const scrubbed = raw
      .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, "Bearer [redacted]")
      .replace(/oat_[A-Za-z0-9_]+/gi, "oat_[redacted]");
    back.searchParams.set("mcp_error", `Saving MCP config failed: ${scrubbed}`);
    return NextResponse.redirect(back);
  }

  // Wire the new token into every agent's harness config so running
  // agents actually see the MCP tool surface. Without this step the
  // Connections page reads "Connected" (because the probe finds the
  // token) but Greg / Ana can't call any of the catalog's tools because
  // the adapter config file was never updated.
  try {
    const { registerCatalogMcpForProject } = await import(
      "@/server/mcp-server/registration"
    );
    const results = await registerCatalogMcpForProject(
      pending.project_slug,
      pending.catalog_key,
    );
    const failed = results.filter((r) => !r.ok);
    if (failed.length > 0) {
      console.warn(
        `[mcp-oauth] ${failed.length}/${results.length} agents failed to register ${pending.catalog_key}:`,
        failed.map((f) => (f.ok ? null : f.error)).filter(Boolean),
      );
    }
  } catch (err) {
    console.error("[mcp-oauth] registerCatalogMcpForProject threw:", err);
  }

  // Kick off account analysis for platforms we can propose goals from.
  // Fire-and-forget: the goals index shows the run's progress and the
  // resulting suggestion cards.
  try {
    const { generateSuggestionsForSource, suggestionSourceLabel } = await import(
      "@/server/suggestions/engine"
    );
    if (suggestionSourceLabel(pending.catalog_key)) {
      void generateSuggestionsForSource(pending.project_slug, pending.catalog_key);
      back.searchParams.set("mcp_analyzing", "1");
    }
  } catch (err) {
    console.error("[mcp-oauth] suggestion generation kickoff failed:", err);
  }

  // Multi-account MCPs (Google Ads, Meta Ads, GSC): resolve the workspace's
  // account/property selection now, server-side. A still-valid existing
  // selection is kept, a bearer with exactly one account is persisted
  // silently, and only a genuine choice appends `mcp_key` — which makes the
  // Connections page open the picker dialog on the matching card.
  try {
    const { resolvePostConnectSelection } = await import(
      "@/server/mcp/account-selection"
    );
    const selection = await resolvePostConnectSelection(
      pending.project_slug,
      pending.catalog_key,
    );
    if (selection.kind === "choice_required") {
      back.searchParams.set("mcp_key", pending.catalog_key);
    }
  } catch (err) {
    console.error("[mcp-oauth] post-connect account resolution threw:", err);
    const { accountPickerFor } = await import("@/lib/mcp-account-pickers");
    if (accountPickerFor(pending.catalog_key)) {
      back.searchParams.set("mcp_key", pending.catalog_key);
    }
  }

  // Flash banner uses the catalog name (what the user recognizes), not the
  // project-prefixed server key.
  back.searchParams.set("mcp_connected", pending.display_name);
  return NextResponse.redirect(back);
}

function htmlErrorPage(message: string): Response {
  // Shown only when we can't even resolve the pending flow, so we have no
  // agent slug to redirect to. Bare minimal HTML — Tailwind isn't loaded.
  const body = `<!doctype html><html><body style="font-family:system-ui;padding:2rem;max-width:36rem;margin:auto">
<h1 style="margin:0 0 1rem;font-size:1.25rem">Couldn’t complete MCP connection</h1>
<p style="color:#666">${escapeHtml(message)}</p>
<p style="margin-top:2rem"><a href="/">← Back to app</a></p>
</body></html>`;
  return new Response(body, {
    status: 400,
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function truncate(s: string, n: number): string {
  return s.length > n ? `${s.slice(0, n)}…` : s;
}

import "@testing-library/jest-dom/vitest";

// Node 25 exposes an experimental, path-dependent global localStorage that can
// shadow jsdom's implementation. Keep component tests independent of the Node
// invocation flags by installing the small, standards-compatible subset they
// need in every DOM test environment.
if (typeof window !== "undefined") {
  const values = new Map<string, string>();
  const localStorage: Storage = {
    get length() {
      return values.size;
    },
    clear() {
      values.clear();
    },
    getItem(key) {
      return values.get(String(key)) ?? null;
    },
    key(index) {
      return [...values.keys()][index] ?? null;
    },
    removeItem(key) {
      values.delete(String(key));
    },
    setItem(key, value) {
      values.set(String(key), String(value));
    },
  };

  Object.defineProperty(window, "localStorage", {
    configurable: true,
    value: localStorage,
  });
}

